import { Metric } from '../observability/metrics.js';
import {
  createExpiredSessionCookie,
  createSessionCookie,
  readSessionToken,
} from '../security/session-cookie.js';
import { assertSameOrigin } from './assert-same-origin.js';
import { HttpError } from './http-error.js';
import { readJsonBody } from './read-json-body.js';

const NO_SESSION_ERROR = 'No estás en ninguna sala';
const ROOM_NOT_FOUND_ERROR = 'La sala no existe o el enlace ya no es válido';
const SERVER_FULL_ERROR = 'El servidor está lleno por ahora. Inténtalo más tarde.';
const TOO_MANY_ATTEMPTS_ERROR = 'Demasiados intentos. Espera un minuto.';
const RETRY_AFTER_SECONDS = '60';

// Ciclo de vida de una persona en una sala: crearla, unirse, consultar y salir.
// Cada sesion pertenece a una sola sala, fijada al crearla.
export class RoomEndpoint {
  #rooms;
  #sessions;
  #limiters;
  #readAddress;
  #referenceClient;
  #responder;
  #metrics;
  #logger;
  #onSessionRevoked;

  constructor(dependencies) {
    this.#rooms = dependencies.rooms;
    this.#sessions = dependencies.sessions;
    this.#limiters = dependencies.limiters;
    this.#readAddress = dependencies.readAddress;
    this.#referenceClient = dependencies.referenceClient;
    this.#responder = dependencies.responder;
    this.#metrics = dependencies.metrics;
    this.#logger = dependencies.logger;
    this.#onSessionRevoked = dependencies.onSessionRevoked;
  }

  routes() {
    return new Map([
      ['/rooms', { POST: (request, response) => this.#create(request, response) }],
      ['/rooms/join', { POST: (request, response) => this.#join(request, response) }],
      [
        '/session',
        {
          GET: (request, response) => this.#status(request, response),
          DELETE: (request, response) => this.#leave(request, response),
        },
      ],
    ]);
  }

  // Una sesion solo es valida mientras su sala siga existiendo.
  requireSession(request) {
    const session = this.#sessions.find(readSessionToken(request));
    if (!session || !this.#rooms.find(session.roomId)) {
      throw new HttpError(401, NO_SESSION_ERROR);
    }
    return session;
  }

  #create(request, response) {
    this.#assertAllowed(request, this.#limiters.create);
    const room = this.#rooms.create();
    if (!room) {
      throw new HttpError(503, SERVER_FULL_ERROR);
    }
    this.#metrics.increment(Metric.ROOMS_CREATED);
    this.#logger.info('room.created', { roomId: room.id });
    this.#startSession(request, response, { roomId: room.id, isOwner: true });
  }

  async #join(request, response) {
    this.#assertAllowed(request, this.#limiters.join);
    const { inviteToken } = (await readJsonBody(request)) ?? {};
    const room = typeof inviteToken === 'string' ? this.#rooms.findByInvite(inviteToken) : null;
    if (!room) {
      this.#metrics.increment(Metric.JOINS_FAILED);
      this.#logger.warn('room.join.denied', { clientRef: this.#clientRef(request) });
      throw new HttpError(404, ROOM_NOT_FOUND_ERROR);
    }
    this.#logger.info('room.joined', { roomId: room.id });
    this.#startSession(request, response, { roomId: room.id, isOwner: false });
  }

  #status(request, response) {
    const session = this.requireSession(request);
    const room = this.#rooms.find(session.roomId);
    this.#responder.json(response, 200, { inviteToken: room.inviteToken, isOwner: session.isOwner });
  }

  #leave(request, response) {
    assertSameOrigin(request);
    const token = readSessionToken(request);
    const session = this.#sessions.find(token);
    if (session) {
      this.#endSession(token, session);
    }
    this.#responder.empty(response, { 'Set-Cookie': createExpiredSessionCookie() });
  }

  #assertAllowed(request, limiter) {
    assertSameOrigin(request);
    if (!limiter.allow(this.#readAddress(request))) {
      this.#logger.warn('http.rate_limited', { clientRef: this.#clientRef(request) });
      throw new HttpError(429, TOO_MANY_ATTEMPTS_ERROR, { 'Retry-After': RETRY_AFTER_SECONDS });
    }
  }

  // Entrar a una sala reemplaza la sesion anterior del navegador, si la habia.
  #startSession(request, response, attributes) {
    const previousToken = readSessionToken(request);
    const previousSession = this.#sessions.find(previousToken);
    if (previousSession) {
      this.#endSession(previousToken, previousSession);
    }
    const created = this.#sessions.create(attributes);
    if (!created) {
      throw new HttpError(503, SERVER_FULL_ERROR);
    }
    this.#responder.empty(response, {
      'Set-Cookie': createSessionCookie(created.token, this.#sessions.ttlMs),
    });
  }

  #endSession(token, session) {
    this.#sessions.revoke(token);
    this.#onSessionRevoked(session);
    this.#logger.info('session.ended', { sessionId: session.id });
  }

  #clientRef(request) {
    return this.#referenceClient(this.#readAddress(request));
  }
}

