import { assertSameOrigin } from '../http/assert-same-origin.js';
import { readJsonBody } from '../http/read-json-body.js';
import { Metric } from '../observability/metrics.js';
import { requireName } from '../validation.js';
import { apiError, ApiErrorCode } from './api-error.js';

const TOKEN_TYPE = 'Bearer';
const RETRY_AFTER_SECONDS = '60';
const INVALID_INVITE_ERROR = 'inviteToken debe ser texto';
const INVITE_NOT_FOUND_ERROR = 'La sala no existe o la invitación ya no es válida';
const NAME_TAKEN_ERROR = 'Ese nombre ya lo usa otra persona de esta sala';
const SERVER_FULL_ERROR = 'El servidor está lleno por ahora. Inténtalo más tarde.';
const TOO_MANY_ATTEMPTS_ERROR = 'Demasiados intentos. Espera un minuto.';

// requireName solo lanza ValidationError, cuyo mensaje esta pensado para mostrarse.
function requireApiName(rawName) {
  try {
    return requireName(rawName);
  } catch (error) {
    throw apiError(400, ApiErrorCode.INVALID_NAME, error.message);
  }
}

// Inicio y cierre de sesion de la API REST. Sin invitacion se crea una sala nueva y quien
// entra es su dueno; con invitacion se une a una sala existente. El nombre queda reservado
// en la sala mientras dure la sesion y el token viaja en Authorization: Bearer.
export class ApiAuthEndpoint {
  #authenticator;
  #rooms;
  #sessions;
  #limiters;
  #readAddress;
  #responder;
  #logger;
  #metrics;
  #onLogout;

  constructor(dependencies) {
    this.#authenticator = dependencies.authenticator;
    this.#rooms = dependencies.rooms;
    this.#sessions = dependencies.sessions;
    this.#limiters = dependencies.limiters;
    this.#readAddress = dependencies.readAddress;
    this.#responder = dependencies.responder;
    this.#logger = dependencies.logger;
    this.#metrics = dependencies.metrics;
    this.#onLogout = dependencies.onLogout;
  }

  routes() {
    return new Map([
      ['/api/v1/auth/login', { POST: (request, response) => this.#login(request, response) }],
      ['/api/v1/auth/logout', { POST: (request, response) => this.#logout(request, response) }],
    ]);
  }

  async #login(request, response) {
    assertSameOrigin(request);
    const body = Object(await readJsonBody(request));
    const name = requireApiName(body.name);
    const isOwner = body.inviteToken === undefined;
    const room = isOwner ? this.#openRoom(request) : this.#findRoom(request, body.inviteToken);
    const { token, session } = this.#startSession(room, name, isOwner);
    this.#metrics.increment(Metric.API_LOGINS);
    this.#logger.info('api.login', { roomId: room.id, sessionId: session.id, isOwner });
    this.#responder.json(response, 201, {
      tokenType: TOKEN_TYPE,
      accessToken: token,
      expiresIn: Math.floor(this.#sessions.ttlMs / 1000),
      user: { id: session.id, name: session.name, isOwner },
      room: { id: room.id, inviteToken: room.inviteToken },
    });
  }

  #logout(request, response) {
    const { token, session, room } = this.#authenticator.authenticate(request);
    this.#sessions.revoke(token);
    this.#onLogout(session, room);
    this.#logger.info('api.logout', { sessionId: session.id });
    this.#responder.empty(response);
  }

  #openRoom(request) {
    this.#assertAllowed(request, this.#limiters.create);
    const room = this.#rooms.create();
    if (!room) {
      throw apiError(503, ApiErrorCode.SERVER_FULL, SERVER_FULL_ERROR);
    }
    this.#metrics.increment(Metric.ROOMS_CREATED);
    this.#logger.info('room.created', { roomId: room.id });
    return room;
  }

  #findRoom(request, inviteToken) {
    this.#assertAllowed(request, this.#limiters.join);
    if (typeof inviteToken !== 'string') {
      throw apiError(400, ApiErrorCode.INVALID_INVITE, INVALID_INVITE_ERROR);
    }
    const room = this.#rooms.findByInvite(inviteToken);
    if (!room) {
      this.#metrics.increment(Metric.JOINS_FAILED);
      throw apiError(404, ApiErrorCode.INVITE_NOT_FOUND, INVITE_NOT_FOUND_ERROR);
    }
    return room;
  }

  #startSession(room, name, isOwner) {
    if (!room.names.isAvailableFor(null, name)) {
      throw apiError(409, ApiErrorCode.NAME_TAKEN, NAME_TAKEN_ERROR);
    }
    const created = this.#sessions.create({ roomId: room.id, isOwner, name });
    if (!created) {
      throw apiError(503, ApiErrorCode.SERVER_FULL, SERVER_FULL_ERROR);
    }
    room.names.claim(created.session.id, name);
    this.#rooms.markOccupied(room);
    return created;
  }

  #assertAllowed(request, limiter) {
    if (!limiter.allow(this.#readAddress(request))) {
      throw apiError(429, ApiErrorCode.RATE_LIMITED, TOO_MANY_ATTEMPTS_ERROR, {
        'Retry-After': RETRY_AFTER_SECONDS,
      });
    }
  }
}

