import { isIP } from 'node:net';

// Cabeceras que un proxy de confianza escribe con la IP real y sobrescribe si el cliente
// la envia: Cloudflare (CF-Connecting-IP) y el borde de Railway (X-Real-IP). Nunca se usa
// X-Forwarded-For, cuyo primer elemento lo puede inventar el cliente.
const PROXY_HEADER_READERS = new Map([
  ['cf-connecting-ip', (request) => request.headers['cf-connecting-ip']],
  ['x-real-ip', (request) => request.headers['x-real-ip']],
]);

export const TRUSTED_PROXY_HEADERS = Object.freeze([...PROXY_HEADER_READERS.keys()]);

function readSocketAddress(request) {
  return request.socket.remoteAddress;
}

// Solo es seguro si el puerto no es accesible sin pasar por ese proxy: de lo contrario
// cualquiera podria falsificar la cabecera y evadir los limites. Un valor ausente o que
// no sea una IP valida se ignora y se usa la direccion del socket.
export function createAddressReader({ trustedProxyHeader = null } = {}) {
  const readForwardedAddress = PROXY_HEADER_READERS.get(trustedProxyHeader);
  if (!readForwardedAddress) {
    return readSocketAddress;
  }
  return (request) => {
    const forwardedAddress = readForwardedAddress(request);
    return isIP(forwardedAddress ?? '') ? forwardedAddress : readSocketAddress(request);
  };
}

src/server/security/connection-guard.js.source:
export const DEFAULT_MAX_CONNECTIONS = 200;
export const DEFAULT_MAX_CONNECTIONS_PER_ADDRESS = 30;

// Cada conexion ocupa memoria en el servidor: sin este tope, una sola maquina podria agotarla.
// El limite por direccion es holgado porque varias computadoras pueden compartir la misma IP.
export class ConnectionGuard {
  #maxConnections;
  #maxConnectionsPerAddress;
  #connectionsByAddress = new Map();
  #totalConnections = 0;

  constructor({
    maxConnections = DEFAULT_MAX_CONNECTIONS,
    maxConnectionsPerAddress = DEFAULT_MAX_CONNECTIONS_PER_ADDRESS,
  } = {}) {
    this.#maxConnections = maxConnections;
    this.#maxConnectionsPerAddress = maxConnectionsPerAddress;
  }

  admits(address) {
    return (
      this.#totalConnections < this.#maxConnections &&
      this.#countFor(address) < this.#maxConnectionsPerAddress
    );
  }

  track(address) {
    this.#totalConnections += 1;
    this.#connectionsByAddress.set(address, this.#countFor(address) + 1);
  }

  release(address) {
    this.#totalConnections -= 1;
    const remaining = this.#countFor(address) - 1;
    if (remaining > 0) {
      this.#connectionsByAddress.set(address, remaining);
    } else {
      this.#connectionsByAddress.delete(address);
    }
  }

  #countFor(address) {
    return this.#connectionsByAddress.get(address) ?? 0;
  }
}

src/server/security/origin-guard.js.source:
// Evita que otra pagina web abra un WebSocket desde el navegador de un visitante.
// Los clientes fuera del navegador no envian Origin y podrian falsificarlo, asi que
// esta regla no los frena: para ellos existen el limite de mensajes y la validacion.
export function isSameOrigin(origin, host) {
  if (origin === undefined) {
    return true;
  }
  try {
    return new URL(origin).host === host;
  } catch {
    return false;
  }
}

